class DBConnection:
    def __enter__(self):
        print('Подключение открыто')
        self.conn = 'active'
        return self.conn
    def __exit__(self, exc_type, exc_val, exc_tb):
        print('Подключение закрыто')
        return False

with DBConnection() as conn:
    print(f'Работа с {conn}')

