class T:
    def __enter__(self):
        print('enter')
        return 'x'
    def __exit__(self, *args):
        print('exit')

t = T()
with t as val:
    print(val)

from contextlib import contextmanager

@contextmanager
def tag():
    yield 'X'

with tag() as val:
    print(val)

